  import { CreateProductInput, ProductDto } from "./dtos";
  import { DomainError } from "../domain/errors";
  import { Product } from "../domain/product";
  import { ProductRepository } from "../domain/repositories";

  export class InventoryService {
    public constructor(private readonly products: ProductRepository) {}

    public addProduct(input: CreateProductInput): ProductDto {
      if (this.products.findById(input.id)) {
        throw new DomainError(`Product ${input.id} already exists`);
      }
      const product = new Product(input.id, input.name, input.stock);
      this.products.save(product);
      return this.toDto(product);
    }

    public listProducts(): ProductDto[] {
      return this.products.list().map((product) => this.toDto(product));
    }

    private toDto(product: Product): ProductDto {
      return { id: product.id, name: product.name, stock: product.stock };
    }
  }

  =====SOURCE-END=====

